// Add at the top of lib/excel.ts
const excelCache = new Map<string, { buffer: ArrayBuffer; timestamp: number }>();
const CACHE_EXPIRY_MS = 10 * 60 * 1000; // 10 minutes

export async function exportToExcel(reports: DailyReport[], filename: string = 'gial-dsr-report.xlsx') {
  // Create hash of reports for caching
  const reportsHash = JSON.stringify(reports.map(r => ({
    id: r.id,
    report_date: r.report_date,
    sample_count: r.sample_count,
    evk_status: r.evk_status
  })));

  // Check cache
  const cached = excelCache.get(reportsHash);
  if (cached && (Date.now() - cached.timestamp < CACHE_EXPIRY_MS)) {
    saveAs(new Blob([cached.buffer]), filename);
    return;
  }

  // Generate new Excel file (existing code)
  const workbook = new ExcelJS.Workbook();
  // ... rest of function ...

  const buffer = await workbook.xlsx.writeBuffer();

  // Cache result
  excelCache.set(reportsHash, { buffer, timestamp: Date.now() });

  // Clean old cache entries
  if (excelCache.size > 10) {
    const oldestKey = Array.from(excelCache.keys()).reduce((a, b) => 
      excelCache.get(a)!.timestamp < excelCache.get(b)!.timestamp ? a : b
    );
    excelCache.delete(oldestKey);
  }

  saveAs(new Blob([buffer]), filename);
}
